#!/bin/sh
python3 -c 'q='"'"'import json\nsrc="q="+repr(q)+";exec(q)"\nR={"0,*":[0,"=",1]};m=json.dumps(R,separators=(",",":"));s=m\nh=0;t=list(s);hist=[]\nwhile h<len(t):\n hist.append([0,h,"".join(t)]);h+=1\nhist.append([0,h,"".join(t)])\nb=json.dumps([R,s,hist],separators=(",",":")).encode()\ndef G(b):\n n=1\n for v in b:n=n*257+v+1\n return n\ndef D(n):\n a=[]\n while n>1:\n  n,r=divmod(n,257);assert r;a.append(r-1)\n return bytes(a[::-1])\na=G(b);e=G(src.encode());assert D(a)==b and D(e)==src.encode()\np=[];k=2;g=1\nwhile len(p)<len(b):\n if all(k%d for d in p if d*d<=k):p.append(k)\n k+=1\nfor d,v in zip(p,b):g*=d**(v+1)\nz=g;out=[]\nfor d in p:\n v=0\n while z%d==0:z//=d;v+=1\n out.append(v-1)\nassert z==1 and bytes(out)==b\ncopy=src;assert copy==src\nprint(json.dumps(dict(steps=h,self_input=s==m,read_all=h==len(s),source_copy=copy==src,source_roundtrip=D(e)==src.encode(),history_roundtrip=D(a)==b,prime_roundtrip=bytes(out)==b,history_bytes=len(b),source_bits=e.bit_length(),base257_bits=a.bit_length(),prime_bits=g.bit_length())))'"'"';exec(q)'